/// Execution unit.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Unit {
    /// vector ALU
    Valu,
    /// transcendental unit
    Trans,
    /// matrix unit (WMMA)
    Wmma,
    /// scalar ALU
    Salu,
    /// scalar memory
    Smem,
    /// vector memory (global, buffer, scratch)
    Vmem,
    /// local data share
    Lds,
    /// branch
    Branch,
    /// program control: waits, hints, barriers, priority, end
    Ctrl,
    /// pseudo instruction, expanded or dropped before encoding
    Pseudo,
    /// other
    Other,
}

/// Execution unit of an opcode.
#[inline]
pub fn unit(op: Opc) -> Unit {
    match op {
        Opc::SMovB32 | Opc::SMovB64 | Opc::SNotB32 | Opc::SAndSaveexecB32 | Opc::SAddU32 | Opc::SSubU32
        | Opc::SAddI32 | Opc::SSubI32 | Opc::SAddcU32 | Opc::SSubbU32 | Opc::SLshlB32 | Opc::SLshlB64
        | Opc::SLshrB32 | Opc::SLshrB64 | Opc::SAshrI32 | Opc::SAshrI64 | Opc::SLshl1AddU32 | Opc::SLshl2AddU32
        | Opc::SLshl3AddU32 | Opc::SLshl4AddU32 | Opc::SMinI32 | Opc::SMinU32 | Opc::SMaxI32 | Opc::SMaxU32
        | Opc::SAndB32 | Opc::SAndB64 | Opc::SOrB32 | Opc::SOrB64 | Opc::SXorB32 | Opc::SXorB64
        | Opc::SAndNot1B32 | Opc::SOrNot1B32 | Opc::SBfeU32 | Opc::SMulI32 | Opc::SMulHiU32 | Opc::SMulHiI32
        | Opc::SCselectB32 | Opc::SCselectB64 | Opc::SCmpEqI32 | Opc::SCmpLgI32 | Opc::SCmpGtI32
        | Opc::SCmpGeI32 | Opc::SCmpLtI32 | Opc::SCmpLeI32 | Opc::SCmpEqU32 | Opc::SCmpLgU32 | Opc::SCmpGtU32
        | Opc::SCmpGeU32 | Opc::SCmpLtU32 | Opc::SCmpLeU32 | Opc::SCmpEqU64 | Opc::SCmpLgU64 | Opc::SMovkI32
        | Opc::SWaitcntVscnt | Opc::SAndSaveexecB64 | Opc::SNotB64 | Opc::SAndNot1B64 | Opc::SOrNot1B64 => Unit::Salu,
        Opc::SNop | Opc::SClause | Opc::SDelayAlu | Opc::SWaitcnt | Opc::SCodeEnd | Opc::SEndpgm | Opc::SSendmsg
        | Opc::SBarrier | Opc::SBarrierLds | Opc::SBarrierBare | Opc::SSetprio | Opc::SWaitcntExplicit => Unit::Ctrl,
        Opc::SBranch | Opc::SCbranchScc0 | Opc::SCbranchScc1 | Opc::SCbranchExecz | Opc::SCbranchExecnz => Unit::Branch,
        Opc::SLoadB32 | Opc::SLoadB64 | Opc::SLoadB128 | Opc::SLoadB256 | Opc::SLoadB512 => Unit::Smem,
        Opc::VNop | Opc::VMovB32 | Opc::VReadfirstlaneB32 | Opc::VCvtF32I32 | Opc::VCvtF32U32 | Opc::VCvtU32F32
        | Opc::VCvtI32F32 | Opc::VCvtF16F32 | Opc::VCvtF32F16 | Opc::VMovB16 | Opc::VTruncF32 | Opc::VMovB32Dpp
        | Opc::VMovB32Dpp8 | Opc::VNotB32 | Opc::VCndmaskB32 | Opc::VAddF32 | Opc::VSubF32 | Opc::VSubrevF32
        | Opc::VMulF32 | Opc::VMulI32I24 | Opc::VMulU32U24 | Opc::VMulHiU32U24 | Opc::VMinF32 | Opc::VMaxF32
        | Opc::VMinI32 | Opc::VMaxI32 | Opc::VMinU32 | Opc::VMaxU32 | Opc::VLshlrevB32 | Opc::VLshrrevB32
        | Opc::VAshrrevI32 | Opc::VAndB32 | Opc::VOrB32 | Opc::VXorB32 | Opc::VAddCoCiU32 | Opc::VSubCoCiU32
        | Opc::VAddNcU32 | Opc::VSubNcU32 | Opc::VSubrevNcU32 | Opc::VFmacF32 | Opc::VMadU32U24 | Opc::VBfeU32
        | Opc::VBfeI32 | Opc::VFmaF32 | Opc::VMin3F32 | Opc::VMax3F32 | Opc::VMed3I32 | Opc::VDivFixupF32
        | Opc::VDivFmasF32 | Opc::VPermB32 | Opc::VLshlAddU32 | Opc::VAddLshlU32 | Opc::VAdd3U32
        | Opc::VLshlOrB32 | Opc::VAndOrB32 | Opc::VOr3B32 | Opc::VMaxminI32 | Opc::VMinmaxI32
        | Opc::VPermlane16B32 | Opc::VPermlanex16B32 | Opc::VMbcntLoU32B32 | Opc::VDivScaleF32 | Opc::VMadU64U32
        | Opc::VMadI64I32 | Opc::VAddCoU32 | Opc::VSubCoU32 | Opc::VSubrevCoU32 | Opc::VPackB32F16
        | Opc::VLdexpF32 | Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32 | Opc::VLshlrevB64
        | Opc::VLshrrevB64 | Opc::VAshrrevI64 | Opc::VPkFmaF16 | Opc::VPkAddF16 | Opc::VPkMulF16
        | Opc::VDot2F32F16 | Opc::VFmaMixF32 | Opc::VFmaMixloF16 | Opc::VFmaMixhiF16 | Opc::VDual
        | Opc::VReadlaneB32 | Opc::VWritelaneB32 | Opc::VRndneF32 | Opc::VFmaF64 | Opc::VAddF64 | Opc::VMulF64
        | Opc::VMaxF64 | Opc::VMinF64 | Opc::VLdexpF64 | Opc::VDivScaleF64 | Opc::VDivFmasF64
        | Opc::VDivFixupF64 | Opc::VDot2F32Bf16 | Opc::VMbcntHiU32B32 => Unit::Valu,
        Opc::VExpF32 | Opc::VLogF32 | Opc::VRcpF32 | Opc::VRcpIflagF32 | Opc::VRsqF32 | Opc::VRcpF64 => Unit::Trans,
        Opc::VWmmaF32F16 | Opc::VWmmaF32F16Early | Opc::VWmmaF32Bf16 | Opc::VWmmaF32Bf16Early | Opc::VWmmaI32Iu8
        | Opc::VWmmaI32Iu8Early | Opc::VWmmaI32Iu4 | Opc::VWmmaI32Iu4Early => Unit::Wmma,
        Opc::DsAddU32 | Opc::DsAddF32 | Opc::DsAddRtnU32 | Opc::DsAddRtnF32 | Opc::DsStoreB32
        | Opc::DsStore2addrB32 | Opc::DsStoreB16 | Opc::DsSwizzleB32 | Opc::DsLoadB32 | Opc::DsLoadU16
        | Opc::DsStoreB64 | Opc::DsLoadB64 | Opc::DsStoreB16D16Hi | Opc::DsLoadU16D16 | Opc::DsLoadU16D16Hi
        | Opc::DsBpermuteB32 | Opc::DsStoreB128 | Opc::DsLoadB128 | Opc::DsLoadU8 | Opc::DsStoreB8
        | Opc::DsStoreB8D16Hi => Unit::Lds,
        Opc::GLoadU16 | Opc::GLoadB32 | Opc::GLoadB64 | Opc::GLoadB96 | Opc::GLoadB128 | Opc::GStoreB16
        | Opc::GStoreB32 | Opc::GStoreB64 | Opc::GStoreB96 | Opc::GStoreB128 | Opc::GLoadD16B16
        | Opc::GLoadD16HiB16 | Opc::GStoreD16HiB16 | Opc::GAtomicAddU32 | Opc::GAtomicAddF32
        | Opc::ScratchLoadB32 | Opc::ScratchLoadB64 | Opc::ScratchLoadB96 | Opc::ScratchLoadB128
        | Opc::ScratchStoreB32 | Opc::ScratchStoreB64 | Opc::ScratchStoreB96 | Opc::ScratchStoreB128
        | Opc::GAtomicAddU32Rtn | Opc::GAtomicAddF32Rtn | Opc::BufLoadB32 | Opc::BufLoadB64 | Opc::BufLoadB128
        | Opc::BufStoreB16 | Opc::BufStoreB32 | Opc::BufStoreB64 | Opc::BufStoreB128 | Opc::BufLoadU16
        | Opc::BufLoadD16B16 | Opc::BufLoadD16HiB16 | Opc::BufStoreD16HiB16 | Opc::GLoadU8 | Opc::GStoreB8
        | Opc::GStoreD16HiB8 | Opc::BufferGl0Inv | Opc::BufferGl1Inv => Unit::Vmem,
        Opc::Copy | Opc::ImplicitDef | Opc::PackF16 | Opc::SchedBarrier => Unit::Pseudo,
        Opc::VCmp(_) => Unit::Valu,
        Opc::Gfx9(_) => Unit::Pseudo,
    }
}

/// Issue cycles of an opcode on one SIMD (the BURS prototype's cost; nothing else reads it).
#[inline]
pub fn issue(op: Opc) -> u32 {
    match op {
        Opc::SMovB32 | Opc::SMovB64 | Opc::SNotB32 | Opc::SAndSaveexecB32 | Opc::SAddU32 | Opc::SSubU32
        | Opc::SAddI32 | Opc::SSubI32 | Opc::SAddcU32 | Opc::SSubbU32 | Opc::SLshlB32 | Opc::SLshlB64
        | Opc::SLshrB32 | Opc::SLshrB64 | Opc::SAshrI32 | Opc::SAshrI64 | Opc::SLshl1AddU32 | Opc::SLshl2AddU32
        | Opc::SLshl3AddU32 | Opc::SLshl4AddU32 | Opc::SMinI32 | Opc::SMinU32 | Opc::SMaxI32 | Opc::SMaxU32
        | Opc::SAndB32 | Opc::SAndB64 | Opc::SOrB32 | Opc::SOrB64 | Opc::SXorB32 | Opc::SXorB64
        | Opc::SAndNot1B32 | Opc::SOrNot1B32 | Opc::SBfeU32 | Opc::SCselectB32 | Opc::SCselectB64
        | Opc::SCmpEqI32 | Opc::SCmpLgI32 | Opc::SCmpGtI32 | Opc::SCmpGeI32 | Opc::SCmpLtI32 | Opc::SCmpLeI32
        | Opc::SCmpEqU32 | Opc::SCmpLgU32 | Opc::SCmpGtU32 | Opc::SCmpGeU32 | Opc::SCmpLtU32 | Opc::SCmpLeU32
        | Opc::SCmpEqU64 | Opc::SCmpLgU64 | Opc::SMovkI32 | Opc::SWaitcntVscnt | Opc::SBranch
        | Opc::SCbranchScc0 | Opc::SCbranchScc1 | Opc::SCbranchExecz | Opc::SCbranchExecnz | Opc::VNop
        | Opc::VMovB32 | Opc::VReadfirstlaneB32 | Opc::VCvtF32I32 | Opc::VCvtF32U32 | Opc::VCvtU32F32
        | Opc::VCvtI32F32 | Opc::VCvtF16F32 | Opc::VCvtF32F16 | Opc::VMovB16 | Opc::VTruncF32 | Opc::VNotB32
        | Opc::VCndmaskB32 | Opc::VAddF32 | Opc::VSubF32 | Opc::VSubrevF32 | Opc::VMulF32 | Opc::VMulI32I24
        | Opc::VMulU32U24 | Opc::VMulHiU32U24 | Opc::VMinF32 | Opc::VMaxF32 | Opc::VMinI32 | Opc::VMaxI32
        | Opc::VMinU32 | Opc::VMaxU32 | Opc::VLshlrevB32 | Opc::VLshrrevB32 | Opc::VAshrrevI32 | Opc::VAndB32
        | Opc::VOrB32 | Opc::VXorB32 | Opc::VAddCoCiU32 | Opc::VSubCoCiU32 | Opc::VAddNcU32 | Opc::VSubNcU32
        | Opc::VSubrevNcU32 | Opc::VFmacF32 | Opc::VMadU32U24 | Opc::VBfeU32 | Opc::VBfeI32 | Opc::VFmaF32
        | Opc::VMin3F32 | Opc::VMax3F32 | Opc::VMed3I32 | Opc::VDivFixupF32 | Opc::VDivFmasF32 | Opc::VPermB32
        | Opc::VLshlAddU32 | Opc::VAddLshlU32 | Opc::VAdd3U32 | Opc::VLshlOrB32 | Opc::VAndOrB32 | Opc::VOr3B32
        | Opc::VMaxminI32 | Opc::VMinmaxI32 | Opc::VMbcntLoU32B32 | Opc::VDivScaleF32 | Opc::VAddCoU32
        | Opc::VSubCoU32 | Opc::VSubrevCoU32 | Opc::VPackB32F16 | Opc::VLdexpF32 | Opc::VPkFmaF16
        | Opc::VPkAddF16 | Opc::VPkMulF16 | Opc::VDot2F32F16 | Opc::VFmaMixF32 | Opc::VFmaMixloF16
        | Opc::VFmaMixhiF16 | Opc::VDual | Opc::VReadlaneB32 | Opc::VWritelaneB32 | Opc::VRndneF32
        | Opc::VDot2F32Bf16 | Opc::SAndSaveexecB64 | Opc::SNotB64 | Opc::SAndNot1B64 | Opc::SOrNot1B64
        | Opc::VMbcntHiU32B32 => 1,
        Opc::SMulI32 | Opc::SMulHiU32 | Opc::SMulHiI32 | Opc::VLshlrevB64 | Opc::VLshrrevB64 | Opc::VAshrrevI64 => 2,
        Opc::SNop | Opc::SClause | Opc::SDelayAlu | Opc::SWaitcnt | Opc::SCodeEnd | Opc::SEndpgm | Opc::SSendmsg
        | Opc::SBarrier | Opc::SBarrierLds | Opc::SBarrierBare | Opc::SSetprio | Opc::SWaitcntExplicit
        | Opc::Copy | Opc::ImplicitDef | Opc::PackF16 | Opc::SchedBarrier => 0,
        Opc::SLoadB32 | Opc::SLoadB64 | Opc::SLoadB128 | Opc::SLoadB256 | Opc::SLoadB512 | Opc::GLoadU16
        | Opc::GLoadB32 | Opc::GLoadB64 | Opc::GLoadB96 | Opc::GLoadB128 | Opc::GStoreB16 | Opc::GStoreB32
        | Opc::GStoreB64 | Opc::GStoreB96 | Opc::GStoreB128 | Opc::GLoadD16B16 | Opc::GLoadD16HiB16
        | Opc::GStoreD16HiB16 | Opc::GAtomicAddU32 | Opc::GAtomicAddF32 | Opc::ScratchLoadB32
        | Opc::ScratchLoadB64 | Opc::ScratchLoadB96 | Opc::ScratchLoadB128 | Opc::ScratchStoreB32
        | Opc::ScratchStoreB64 | Opc::ScratchStoreB96 | Opc::ScratchStoreB128 | Opc::GAtomicAddU32Rtn
        | Opc::GAtomicAddF32Rtn | Opc::BufLoadB32 | Opc::BufLoadB64 | Opc::BufLoadB128 | Opc::BufStoreB16
        | Opc::BufStoreB32 | Opc::BufStoreB64 | Opc::BufStoreB128 | Opc::BufLoadU16 | Opc::BufLoadD16B16
        | Opc::BufLoadD16HiB16 | Opc::BufStoreD16HiB16 | Opc::GLoadU8 | Opc::GStoreB8 | Opc::GStoreD16HiB8
        | Opc::BufferGl0Inv | Opc::BufferGl1Inv => 5,
        Opc::VMovB32Dpp | Opc::VMovB32Dpp8 | Opc::VPermlane16B32 | Opc::VPermlanex16B32 => 3,
        Opc::VExpF32 | Opc::VLogF32 | Opc::VRcpF32 | Opc::VRcpIflagF32 | Opc::VRsqF32 | Opc::VMadU64U32
        | Opc::VMadI64I32 | Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32 | Opc::DsAddU32 | Opc::DsAddF32
        | Opc::DsAddRtnU32 | Opc::DsAddRtnF32 | Opc::DsStoreB32 | Opc::DsStore2addrB32 | Opc::DsStoreB16
        | Opc::DsSwizzleB32 | Opc::DsLoadB32 | Opc::DsLoadU16 | Opc::DsStoreB64 | Opc::DsLoadB64
        | Opc::DsStoreB16D16Hi | Opc::DsLoadU16D16 | Opc::DsLoadU16D16Hi | Opc::DsBpermuteB32 | Opc::DsStoreB128
        | Opc::DsLoadB128 | Opc::DsLoadU8 | Opc::DsStoreB8 | Opc::DsStoreB8D16Hi | Opc::VRcpF64 => 4,
        Opc::VWmmaF32F16 | Opc::VWmmaF32F16Early | Opc::VWmmaF32Bf16 | Opc::VWmmaF32Bf16Early | Opc::VWmmaI32Iu8
        | Opc::VWmmaI32Iu8Early => 34,
        Opc::VWmmaI32Iu4 | Opc::VWmmaI32Iu4Early => 18,
        Opc::VFmaF64 | Opc::VAddF64 | Opc::VMulF64 | Opc::VMaxF64 | Opc::VMinF64 | Opc::VLdexpF64
        | Opc::VDivScaleF64 | Opc::VDivFmasF64 | Opc::VDivFixupF64 => 32,
        Opc::VCmp(_) => 1,
        Opc::Gfx9(_) => 0,
    }
}

/// Whether an opcode issues to the vector ALU (VALU, transcendental or WMMA).
#[inline]
pub fn is_valu(op: Opc) -> bool {
    matches!(unit(op), Unit::Valu | Unit::Trans | Unit::Wmma)
}

/// s_delay_alu class of an instruction: which kind of result a reader
/// waits for (`Other`: none; `Skip`: a pseudo, which the pass passes by).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Delay {
    Valu,
    Trans,
    Salu,
    Other,
    Skip,
}

/// Wait counters an instruction increments: VMEM loads (`vmcnt`), LDS and
/// SMEM (`lgkmcnt`), SMEM alone (returns out of order).
pub const CNT_VM: u8 = 1;
pub const CNT_LGKM: u8 = 2;
pub const CNT_SMEM: u8 = 4;

/// Latency class.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Lat {
    /// pseudo without a result latency (copies, implicit defs, scheduling barriers)
    Pseudo,
    /// pseudo expanded into VALU instructions
    PseudoValu,
    /// scalar ALU
    Salu,
    /// program control (SOPP): no result; s_delay_alu counts it as SALU
    Ctrl,
    /// vector ALU
    Valu,
    /// transcendental
    Trans,
    /// WMMA: the scheduler waits 16 cycles; s_delay_alu treats it as VALU
    Wmma,
    /// scalar load: lgkmcnt, returns out of order
    Smem,
    /// LDS access: lgkmcnt
    Lds,
    /// vector memory load or returning atomic: vmcnt
    VmemLoad,
    /// vector memory store, atomic without return or cache control
    VmemStore,
}

impl Lat {
    /// Cycles from issue until the scheduler lets a reader of the result issue.
    #[inline]
    pub fn sched(self) -> u32 {
        match self {
            Lat::Pseudo => 0,
            Lat::PseudoValu => 5,
            Lat::Salu => 2,
            Lat::Ctrl => 5,
            Lat::Valu => 5,
            Lat::Trans => 10,
            Lat::Wmma => 16,
            Lat::Smem => 40,
            Lat::Lds => 40,
            Lat::VmemLoad => 300,
            Lat::VmemStore => 5,
        }
    }

    /// s_delay_alu class and the cycles a reader of the result waits.
    #[inline]
    pub fn delay(self) -> (Delay, u8) {
        match self {
            Lat::Pseudo => (Delay::Skip, 0),
            Lat::PseudoValu => (Delay::Skip, 0),
            Lat::Salu => (Delay::Salu, 2),
            Lat::Ctrl => (Delay::Salu, 2),
            Lat::Valu => (Delay::Valu, 5),
            Lat::Trans => (Delay::Trans, 10),
            Lat::Wmma => (Delay::Valu, 5),
            Lat::Smem => (Delay::Other, 0),
            Lat::Lds => (Delay::Other, 0),
            Lat::VmemLoad => (Delay::Other, 0),
            Lat::VmemStore => (Delay::Other, 0),
        }
    }

    /// Whether the instruction clears the s_delay_alu state (a memory
    /// instruction, which waits for VALU results itself).
    #[inline]
    pub fn delay_clears(self) -> bool {
        matches!(self, Lat::Lds | Lat::VmemLoad | Lat::VmemStore)
    }

    /// Wait counters (`CNT_*`) the instruction increments.
    #[inline]
    pub fn counters(self) -> u8 {
        match self {
            Lat::Pseudo => 0,
            Lat::PseudoValu => 0,
            Lat::Salu => 0,
            Lat::Ctrl => 0,
            Lat::Valu => 0,
            Lat::Trans => 0,
            Lat::Wmma => 0,
            Lat::Smem => CNT_LGKM | CNT_SMEM,
            Lat::Lds => CNT_LGKM,
            Lat::VmemLoad => CNT_VM,
            Lat::VmemStore => 0,
        }
    }
}

/// Latency class of an opcode.
#[inline]
pub fn lat(op: Opc) -> Lat {
    match op {
        Opc::SMovB32 | Opc::SMovB64 | Opc::SNotB32 | Opc::SAndSaveexecB32 | Opc::SAddU32 | Opc::SSubU32
        | Opc::SAddI32 | Opc::SSubI32 | Opc::SAddcU32 | Opc::SSubbU32 | Opc::SLshlB32 | Opc::SLshlB64
        | Opc::SLshrB32 | Opc::SLshrB64 | Opc::SAshrI32 | Opc::SAshrI64 | Opc::SLshl1AddU32 | Opc::SLshl2AddU32
        | Opc::SLshl3AddU32 | Opc::SLshl4AddU32 | Opc::SMinI32 | Opc::SMinU32 | Opc::SMaxI32 | Opc::SMaxU32
        | Opc::SAndB32 | Opc::SAndB64 | Opc::SOrB32 | Opc::SOrB64 | Opc::SXorB32 | Opc::SXorB64
        | Opc::SAndNot1B32 | Opc::SOrNot1B32 | Opc::SBfeU32 | Opc::SMulI32 | Opc::SMulHiU32 | Opc::SMulHiI32
        | Opc::SCselectB32 | Opc::SCselectB64 | Opc::SCmpEqI32 | Opc::SCmpLgI32 | Opc::SCmpGtI32
        | Opc::SCmpGeI32 | Opc::SCmpLtI32 | Opc::SCmpLeI32 | Opc::SCmpEqU32 | Opc::SCmpLgU32 | Opc::SCmpGtU32
        | Opc::SCmpGeU32 | Opc::SCmpLtU32 | Opc::SCmpLeU32 | Opc::SCmpEqU64 | Opc::SCmpLgU64 | Opc::SMovkI32
        | Opc::SWaitcntVscnt | Opc::SAndSaveexecB64 | Opc::SNotB64 | Opc::SAndNot1B64 | Opc::SOrNot1B64 => Lat::Salu,
        Opc::SNop | Opc::SClause | Opc::SDelayAlu | Opc::SWaitcnt | Opc::SCodeEnd | Opc::SBranch
        | Opc::SCbranchScc0 | Opc::SCbranchScc1 | Opc::SCbranchExecz | Opc::SCbranchExecnz | Opc::SEndpgm
        | Opc::SSendmsg | Opc::SBarrier | Opc::SBarrierLds | Opc::SBarrierBare | Opc::SSetprio
        | Opc::SWaitcntExplicit => Lat::Ctrl,
        Opc::SLoadB32 | Opc::SLoadB64 | Opc::SLoadB128 | Opc::SLoadB256 | Opc::SLoadB512 => Lat::Smem,
        Opc::VNop | Opc::VMovB32 | Opc::VReadfirstlaneB32 | Opc::VCvtF32I32 | Opc::VCvtF32U32 | Opc::VCvtU32F32
        | Opc::VCvtI32F32 | Opc::VCvtF16F32 | Opc::VCvtF32F16 | Opc::VMovB16 | Opc::VTruncF32 | Opc::VMovB32Dpp
        | Opc::VMovB32Dpp8 | Opc::VNotB32 | Opc::VCndmaskB32 | Opc::VAddF32 | Opc::VSubF32 | Opc::VSubrevF32
        | Opc::VMulF32 | Opc::VMulI32I24 | Opc::VMulU32U24 | Opc::VMulHiU32U24 | Opc::VMinF32 | Opc::VMaxF32
        | Opc::VMinI32 | Opc::VMaxI32 | Opc::VMinU32 | Opc::VMaxU32 | Opc::VLshlrevB32 | Opc::VLshrrevB32
        | Opc::VAshrrevI32 | Opc::VAndB32 | Opc::VOrB32 | Opc::VXorB32 | Opc::VAddCoCiU32 | Opc::VSubCoCiU32
        | Opc::VAddNcU32 | Opc::VSubNcU32 | Opc::VSubrevNcU32 | Opc::VFmacF32 | Opc::VMadU32U24 | Opc::VBfeU32
        | Opc::VBfeI32 | Opc::VFmaF32 | Opc::VMin3F32 | Opc::VMax3F32 | Opc::VMed3I32 | Opc::VDivFixupF32
        | Opc::VDivFmasF32 | Opc::VPermB32 | Opc::VLshlAddU32 | Opc::VAddLshlU32 | Opc::VAdd3U32
        | Opc::VLshlOrB32 | Opc::VAndOrB32 | Opc::VOr3B32 | Opc::VMaxminI32 | Opc::VMinmaxI32
        | Opc::VPermlane16B32 | Opc::VPermlanex16B32 | Opc::VMbcntLoU32B32 | Opc::VDivScaleF32 | Opc::VMadU64U32
        | Opc::VMadI64I32 | Opc::VAddCoU32 | Opc::VSubCoU32 | Opc::VSubrevCoU32 | Opc::VPackB32F16
        | Opc::VLdexpF32 | Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32 | Opc::VLshlrevB64
        | Opc::VLshrrevB64 | Opc::VAshrrevI64 | Opc::VPkFmaF16 | Opc::VPkAddF16 | Opc::VPkMulF16
        | Opc::VDot2F32F16 | Opc::VFmaMixF32 | Opc::VFmaMixloF16 | Opc::VFmaMixhiF16 | Opc::VDual
        | Opc::VReadlaneB32 | Opc::VWritelaneB32 | Opc::VRndneF32 | Opc::VFmaF64 | Opc::VAddF64 | Opc::VMulF64
        | Opc::VMaxF64 | Opc::VMinF64 | Opc::VLdexpF64 | Opc::VDivScaleF64 | Opc::VDivFmasF64
        | Opc::VDivFixupF64 | Opc::VDot2F32Bf16 | Opc::VMbcntHiU32B32 => Lat::Valu,
        Opc::VExpF32 | Opc::VLogF32 | Opc::VRcpF32 | Opc::VRcpIflagF32 | Opc::VRsqF32 | Opc::VRcpF64 => Lat::Trans,
        Opc::VWmmaF32F16 | Opc::VWmmaF32F16Early | Opc::VWmmaF32Bf16 | Opc::VWmmaF32Bf16Early | Opc::VWmmaI32Iu8
        | Opc::VWmmaI32Iu8Early | Opc::VWmmaI32Iu4 | Opc::VWmmaI32Iu4Early => Lat::Wmma,
        Opc::DsAddU32 | Opc::DsAddF32 | Opc::DsAddRtnU32 | Opc::DsAddRtnF32 | Opc::DsStoreB32
        | Opc::DsStore2addrB32 | Opc::DsStoreB16 | Opc::DsSwizzleB32 | Opc::DsLoadB32 | Opc::DsLoadU16
        | Opc::DsStoreB64 | Opc::DsLoadB64 | Opc::DsStoreB16D16Hi | Opc::DsLoadU16D16 | Opc::DsLoadU16D16Hi
        | Opc::DsBpermuteB32 | Opc::DsStoreB128 | Opc::DsLoadB128 | Opc::DsLoadU8 | Opc::DsStoreB8
        | Opc::DsStoreB8D16Hi => Lat::Lds,
        Opc::GLoadU16 | Opc::GLoadB32 | Opc::GLoadB64 | Opc::GLoadB96 | Opc::GLoadB128 | Opc::GLoadD16B16
        | Opc::GLoadD16HiB16 | Opc::ScratchLoadB32 | Opc::ScratchLoadB64 | Opc::ScratchLoadB96
        | Opc::ScratchLoadB128 | Opc::GAtomicAddU32Rtn | Opc::GAtomicAddF32Rtn | Opc::BufLoadB32
        | Opc::BufLoadB64 | Opc::BufLoadB128 | Opc::BufLoadU16 | Opc::BufLoadD16B16 | Opc::BufLoadD16HiB16
        | Opc::GLoadU8 => Lat::VmemLoad,
        Opc::GStoreB16 | Opc::GStoreB32 | Opc::GStoreB64 | Opc::GStoreB96 | Opc::GStoreB128
        | Opc::GStoreD16HiB16 | Opc::GAtomicAddU32 | Opc::GAtomicAddF32 | Opc::ScratchStoreB32
        | Opc::ScratchStoreB64 | Opc::ScratchStoreB96 | Opc::ScratchStoreB128 | Opc::BufStoreB16
        | Opc::BufStoreB32 | Opc::BufStoreB64 | Opc::BufStoreB128 | Opc::BufStoreD16HiB16 | Opc::GStoreB8
        | Opc::GStoreD16HiB8 | Opc::BufferGl0Inv | Opc::BufferGl1Inv => Lat::VmemStore,
        Opc::Copy | Opc::ImplicitDef | Opc::SchedBarrier => Lat::Pseudo,
        Opc::PackF16 => Lat::PseudoValu,
        Opc::VCmp(_) => Lat::Valu,
        Opc::Gfx9(_) => Lat::Pseudo,
    }
}

/// Scheduler result latency of an opcode.
#[inline]
pub fn result_latency(op: Opc) -> u32 {
    lat(op).sched()
}

/// s_delay_alu class and cycles of an opcode.
#[inline]
pub fn delay(op: Opc) -> (Delay, u8) {
    lat(op).delay()
}

/// Whether an opcode clears the s_delay_alu state.
#[inline]
pub fn delay_clears(op: Opc) -> bool {
    lat(op).delay_clears()
}

/// Wait counters an opcode increments.
#[inline]
pub fn counters(op: Opc) -> u8 {
    lat(op).counters()
}

/// WMMA result: the producer side of wmma_ab
pub const HZ_WMMA_D: u32 = 1 << 0;
/// a WMMA reading as A or B the result of the immediately preceding VALU, if that is a WMMA, needs a v_nop between them
pub const HZ_WMMA_AB: u32 = 1 << 1;

