/// `Info` of an opcode. A match whose arms compute a value compiles to a
/// jump table, so the compare family's code-dependent fields are patched
/// in after the load.
#[inline]
pub fn info(op: Opc) -> Info {
    let mut info = INFO[index(op)];
    if let Opc::VCmp(code) = op {
        info.code = code as u16;
        info.vop3 = code as u16;
        info.flags = op.flags();
    }
    info
}

/// Encoding form of an opcode.
#[inline]
pub fn form(op: Opc) -> Form {
    info(op).form
}

/// Whether the table-driven encoder encodes an opcode (else asm.rs's hand encoder does).
#[inline]
pub fn table_encoded(op: Opc) -> bool {
    info(op).table
}

/// Operand role: the encoding field an operand goes to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Role {
    Sdst,
    Ssrc0,
    Exec,
    Ssrc1,
    Sdata,
    Sbase,
    Vdst,
    Src0,
    Src1,
    Src2,
    Vsrc1,
    Old,
    Vdstx,
    Vdsty,
    Srcx,
    Srcy,
    Addr,
    Data0,
    Data1,
    Vaddr,
    Vdata,
    Srsrc,
    Soffset,
    Dst,
    Src,
}

/// Operand class.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Class {
    /// SGPR tuple; as a 1-dword destination also vcc_lo, exec_lo, m0 or null
    S,
    /// scalar source: SGPR, special register, inline constant or literal
    Ss,
    /// EXEC, named as an explicit operand
    X,
    /// VGPR tuple
    V,
    /// vector source: VGPR, SGPR, special register, inline constant or literal
    Vs,
    /// 16-bit half of a VGPR (op_sel or .h picks the high half)
    Vh,
    /// 16-bit vector source: a VGPR half, SGPR or inline constant
    Vsh,
    /// vector source without a literal: VGPR, SGPR or inline constant
    Vi,
    /// any register (pseudo)
    A,
}

/// What `MInst::imm` holds.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Imm {
    /// nothing
    None,
    /// 16-bit immediate field
    Simm16,
    /// wait states minus one
    Nop,
    /// instructions in the clause minus one
    Clause,
    /// s_delay_alu instid0, instskip, instid1
    Delay,
    /// vmcnt, expcnt, lgkmcnt
    Waitcnt,
    /// branch target block (resolved to a word offset by the assembler)
    Label,
    /// message id
    Sendmsg,
    /// 21-bit signed byte offset
    Soff21,
    /// DPP16 control: bits 31:8 of word 1
    Dpp16,
    /// DPP8 lane selects
    Dpp8,
    /// X and Y component opcodes in bits 7:0 and 15:8
    Vopd,
    /// 16-bit unsigned byte offset
    Off16,
    /// two 8-bit dword offsets: offset0 | offset1 << 8
    Off2x8,
    /// ds_swizzle pattern
    Swizzle,
    /// 13-bit signed byte offset
    Off13s,
    /// 12-bit unsigned byte offset
    Off12,
}

/// One operand of a signature: role, class and size in dwords.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Operand {
    pub role: Role,
    pub class: Class,
    pub dwords: u8,
}

/// The operands an instruction takes, in `MInst` order, what its immediate
/// holds and the modifier bits it accepts.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Sig {
    pub defs: &'static [Operand],
    pub uses: &'static [Operand],
    pub imm: Imm,
    pub mods: u32,
}

