/// Operand signature of an opcode.
#[inline]
pub fn signature(op: Opc) -> &'static Sig {
    match op {
        Opc::SMovB32 | Opc::SNotB32 => &SIG_0,
        Opc::SMovB64 | Opc::SNotB64 => &SIG_1,
        Opc::SAndSaveexecB32 => &SIG_2,
        Opc::SAddU32 | Opc::SSubU32 | Opc::SAddI32 | Opc::SSubI32 | Opc::SAddcU32 | Opc::SSubbU32
        | Opc::SLshlB32 | Opc::SLshrB32 | Opc::SAshrI32 | Opc::SLshl1AddU32 | Opc::SLshl2AddU32
        | Opc::SLshl3AddU32 | Opc::SLshl4AddU32 | Opc::SMinI32 | Opc::SMinU32 | Opc::SMaxI32 | Opc::SMaxU32
        | Opc::SAndB32 | Opc::SOrB32 | Opc::SXorB32 | Opc::SAndNot1B32 | Opc::SOrNot1B32 | Opc::SBfeU32
        | Opc::SMulI32 | Opc::SMulHiU32 | Opc::SMulHiI32 | Opc::SCselectB32 => &SIG_3,
        Opc::SLshlB64 | Opc::SLshrB64 | Opc::SAshrI64 => &SIG_4,
        Opc::SAndB64 | Opc::SOrB64 | Opc::SXorB64 | Opc::SCselectB64 | Opc::SAndNot1B64 | Opc::SOrNot1B64 => &SIG_5,
        Opc::SCmpEqI32 | Opc::SCmpLgI32 | Opc::SCmpGtI32 | Opc::SCmpGeI32 | Opc::SCmpLtI32 | Opc::SCmpLeI32
        | Opc::SCmpEqU32 | Opc::SCmpLgU32 | Opc::SCmpGtU32 | Opc::SCmpGeU32 | Opc::SCmpLtU32 | Opc::SCmpLeU32 => &SIG_6,
        Opc::SCmpEqU64 | Opc::SCmpLgU64 => &SIG_7,
        Opc::SMovkI32 | Opc::SWaitcntVscnt => &SIG_8,
        Opc::SNop => &SIG_9,
        Opc::SClause => &SIG_10,
        Opc::SDelayAlu => &SIG_11,
        Opc::SWaitcnt | Opc::SWaitcntExplicit => &SIG_12,
        Opc::SCodeEnd | Opc::SEndpgm | Opc::SBarrier | Opc::SBarrierLds | Opc::SBarrierBare | Opc::VNop
        | Opc::BufferGl0Inv | Opc::BufferGl1Inv | Opc::SchedBarrier => &SIG_13,
        Opc::SBranch | Opc::SCbranchScc0 | Opc::SCbranchScc1 | Opc::SCbranchExecz | Opc::SCbranchExecnz => &SIG_14,
        Opc::SSendmsg => &SIG_15,
        Opc::SSetprio => &SIG_16,
        Opc::SLoadB32 => &SIG_17,
        Opc::SLoadB64 => &SIG_18,
        Opc::SLoadB128 => &SIG_19,
        Opc::SLoadB256 => &SIG_20,
        Opc::SLoadB512 => &SIG_21,
        Opc::VMovB32 | Opc::VCvtF32I32 | Opc::VCvtF32U32 | Opc::VCvtU32F32 | Opc::VCvtI32F32 | Opc::VTruncF32
        | Opc::VExpF32 | Opc::VLogF32 | Opc::VRcpF32 | Opc::VRcpIflagF32 | Opc::VRsqF32 | Opc::VNotB32
        | Opc::VRndneF32 => &SIG_22,
        Opc::VReadfirstlaneB32 => &SIG_23,
        Opc::VCvtF16F32 => &SIG_24,
        Opc::VCvtF32F16 => &SIG_25,
        Opc::VMovB16 => &SIG_26,
        Opc::VMovB32Dpp => &SIG_27,
        Opc::VMovB32Dpp8 => &SIG_28,
        Opc::VCndmaskB32 => &SIG_29,
        Opc::VAddF32 | Opc::VSubF32 | Opc::VSubrevF32 | Opc::VMulF32 | Opc::VMulI32I24 | Opc::VMulU32U24
        | Opc::VMulHiU32U24 | Opc::VMinF32 | Opc::VMaxF32 | Opc::VMinI32 | Opc::VMaxI32 | Opc::VMinU32
        | Opc::VMaxU32 | Opc::VLshlrevB32 | Opc::VLshrrevB32 | Opc::VAshrrevI32 | Opc::VAndB32 | Opc::VOrB32
        | Opc::VXorB32 | Opc::VAddNcU32 | Opc::VSubNcU32 | Opc::VSubrevNcU32 | Opc::VFmacF32 => &SIG_30,
        Opc::VAddCoCiU32 | Opc::VSubCoCiU32 => &SIG_31,
        Opc::VMadU32U24 | Opc::VBfeU32 | Opc::VBfeI32 | Opc::VFmaF32 | Opc::VMin3F32 | Opc::VMax3F32
        | Opc::VMed3I32 | Opc::VDivFixupF32 | Opc::VDivFmasF32 | Opc::VPermB32 | Opc::VLshlAddU32
        | Opc::VAddLshlU32 | Opc::VAdd3U32 | Opc::VLshlOrB32 | Opc::VAndOrB32 | Opc::VOr3B32 | Opc::VMaxminI32
        | Opc::VMinmaxI32 => &SIG_32,
        Opc::VPermlane16B32 | Opc::VPermlanex16B32 => &SIG_33,
        Opc::VMbcntLoU32B32 | Opc::VLdexpF32 | Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32
        | Opc::VMbcntHiU32B32 => &SIG_34,
        Opc::VDivScaleF32 => &SIG_35,
        Opc::VMadU64U32 | Opc::VMadI64I32 => &SIG_36,
        Opc::VAddCoU32 | Opc::VSubCoU32 | Opc::VSubrevCoU32 => &SIG_37,
        Opc::VPackB32F16 => &SIG_38,
        Opc::VLshlrevB64 | Opc::VLshrrevB64 | Opc::VAshrrevI64 => &SIG_39,
        Opc::VPkFmaF16 | Opc::VDot2F32F16 | Opc::VDot2F32Bf16 => &SIG_40,
        Opc::VPkAddF16 | Opc::VPkMulF16 => &SIG_41,
        Opc::VFmaMixF32 | Opc::VFmaMixloF16 => &SIG_42,
        Opc::VFmaMixhiF16 => &SIG_43,
        Opc::VWmmaF32F16 | Opc::VWmmaF32F16Early | Opc::VWmmaF32Bf16 | Opc::VWmmaF32Bf16Early => &SIG_44,
        Opc::VDual => &SIG_45,
        Opc::DsAddU32 | Opc::DsAddF32 | Opc::DsStoreB32 | Opc::DsStoreB16 | Opc::DsStoreB16D16Hi
        | Opc::DsStoreB8 | Opc::DsStoreB8D16Hi => &SIG_46,
        Opc::DsAddRtnU32 | Opc::DsAddRtnF32 | Opc::DsBpermuteB32 => &SIG_47,
        Opc::DsStore2addrB32 => &SIG_48,
        Opc::DsSwizzleB32 => &SIG_49,
        Opc::DsLoadB32 | Opc::DsLoadU16 | Opc::DsLoadU8 => &SIG_50,
        Opc::DsStoreB64 => &SIG_51,
        Opc::DsLoadB64 => &SIG_52,
        Opc::DsLoadU16D16 | Opc::DsLoadU16D16Hi => &SIG_53,
        Opc::DsStoreB128 => &SIG_54,
        Opc::DsLoadB128 => &SIG_55,
        Opc::GLoadU16 | Opc::GLoadB32 | Opc::GLoadU8 => &SIG_56,
        Opc::GLoadB64 => &SIG_57,
        Opc::GLoadB96 => &SIG_58,
        Opc::GLoadB128 => &SIG_59,
        Opc::GStoreB16 | Opc::GStoreB32 | Opc::GStoreD16HiB16 | Opc::GAtomicAddU32 | Opc::GAtomicAddF32
        | Opc::GStoreB8 | Opc::GStoreD16HiB8 => &SIG_60,
        Opc::GStoreB64 => &SIG_61,
        Opc::GStoreB96 => &SIG_62,
        Opc::GStoreB128 => &SIG_63,
        Opc::GLoadD16B16 | Opc::GLoadD16HiB16 => &SIG_64,
        Opc::ScratchLoadB32 => &SIG_65,
        Opc::ScratchLoadB64 => &SIG_66,
        Opc::ScratchLoadB96 => &SIG_67,
        Opc::ScratchLoadB128 => &SIG_68,
        Opc::ScratchStoreB32 => &SIG_69,
        Opc::ScratchStoreB64 => &SIG_70,
        Opc::ScratchStoreB96 => &SIG_71,
        Opc::ScratchStoreB128 => &SIG_72,
        Opc::VReadlaneB32 => &SIG_73,
        Opc::VWritelaneB32 => &SIG_74,
        Opc::GAtomicAddU32Rtn | Opc::GAtomicAddF32Rtn => &SIG_75,
        Opc::BufLoadB32 | Opc::BufLoadU16 => &SIG_76,
        Opc::BufLoadB64 => &SIG_77,
        Opc::BufLoadB128 => &SIG_78,
        Opc::BufStoreB16 | Opc::BufStoreB32 | Opc::BufStoreD16HiB16 => &SIG_79,
        Opc::BufStoreB64 => &SIG_80,
        Opc::BufStoreB128 => &SIG_81,
        Opc::BufLoadD16B16 | Opc::BufLoadD16HiB16 => &SIG_82,
        Opc::VWmmaI32Iu8 | Opc::VWmmaI32Iu8Early => &SIG_83,
        Opc::VWmmaI32Iu4 | Opc::VWmmaI32Iu4Early => &SIG_84,
        Opc::VFmaF64 | Opc::VDivFmasF64 | Opc::VDivFixupF64 => &SIG_85,
        Opc::VAddF64 | Opc::VMulF64 | Opc::VMaxF64 | Opc::VMinF64 => &SIG_86,
        Opc::VLdexpF64 => &SIG_87,
        Opc::VRcpF64 => &SIG_88,
        Opc::VDivScaleF64 => &SIG_89,
        Opc::SAndSaveexecB64 => &SIG_90,
        Opc::Copy => &SIG_91,
        Opc::ImplicitDef => &SIG_92,
        Opc::PackF16 => &SIG_93,
        Opc::VCmp(c) if VCMP64.contains(&c) => &SIG_95,
        Opc::VCmp(_) => &SIG_94,
        Opc::Gfx9(_) => &SIG_13,
    }
}

const VCMP64: [u8; 16] = [0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5a, 0x5b, 0x5c, 0x5d, 0x5e, 0x5f];

