/// Format of an encoding family name (`[fmt]`).
pub fn fmt_of(enc: &str) -> Option<Fmt> {
    match enc {
        "SOP1" => Some(Fmt::Sop1),
        "SOP2" => Some(Fmt::Sop2),
        "SOPC" => Some(Fmt::Sopc),
        "SOPK" => Some(Fmt::Sopk),
        "SOPP" => Some(Fmt::Sopp),
        "SMEM" => Some(Fmt::Smem),
        "VOP1" => Some(Fmt::Vop1),
        "VOP2" => Some(Fmt::Vop2),
        "VOP3" => Some(Fmt::Vop3),
        "VOP3SD" => Some(Fmt::Vop3b),
        "VOPC" => Some(Fmt::Vopc),
        "VOP3P" => Some(Fmt::Vop3p),
        "VOPD" => Some(Fmt::Vopd),
        "DS" => Some(Fmt::Ds),
        "GLOBAL" => Some(Fmt::Global),
        "MUBUF" => Some(Fmt::Mubuf),
        "PSEUDO" => Some(Fmt::Pseudo),
        _ => None,
    }
}
